bool g_scrollToPacks = false; // the Get shader packs card scrolls into view at its next draw (the page opens Library)
// look: an imported look's name, or an imported preset's (preset true; shaders is then 0, the preset names only packs)
struct ImportOffer { std::string look; int shaders = 0; std::vector<std::string> packs; bool preset = false; };
std::optional<ImportOffer> g_offer; // the note card after an import: packs that have shaders the look misses

// A web page in the browser, off the render thread (ShellExecuteW pumps the game window's messages)
void OpenPage(const std::string& url)
{
    HookGuard::StartDetached("Looks: open a pack's page", [url = ApexUtil::ToWide(url)] {
        const HRESULT com = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED | COINIT_DISABLE_OLE1DDE);
        ShellExecuteW(nullptr, L"open", url.c_str(), nullptr, nullptr, SW_SHOWNORMAL);
        if (SUCCEEDED(com)) CoUninitialize();
    });
}

// The pack that would bring run-list entry i (a missing .fx), when one on ReShade's list has it and is not downloaded yet
const Looks::Packs::Pack* PackFor(size_t i)
{
    const auto& e = g.order[i];
    if (Runnable(i) || Looks::Fx::HasFile(e.file)) return nullptr;
    const Looks::Packs::Pack* p = Looks::Packs::PackForFile(e.file, e.technique);
    return p && !Looks::Packs::Downloaded(p->folder) ? p : nullptr;
}

// Packs that would bring the look's missing shaders, and how many shaders they bring
std::vector<std::string> MissingPacks(int* shaders = nullptr)
{
    std::vector<std::string> packs;
    int n = 0;
    for (size_t i = 0; i < g.order.size(); ++i)
        if (const Looks::Packs::Pack* p = PackFor(i))
        {
            ++n;
            if (std::find(packs.begin(), packs.end(), p->folder) == packs.end()) packs.push_back(p->folder);
        }
    if (shaders) *shaders = n;
    return packs;
}

std::string PackName(const std::string& folder)
{
    const Looks::Packs::Pack* p = Looks::Packs::Find(folder);
    return p ? p->name : folder;
}

// "qUINT", "qUINT and AstrayFX", "3 packs"
std::string PackNames(const std::vector<std::string>& folders)
{
    if (folders.size() == 1) return PackName(folders[0]);
    if (folders.size() == 2) return I18n::Trf("{} and {}", PackName(folders[0]), PackName(folders[1]));
    return I18n::Trf("{} packs", folders.size());
}

// "Download <pack>", "Download both", "Download all"
std::string DownloadLabel(const std::vector<std::string>& folders)
{
    if (folders.size() == 1) return I18n::Trf("Download {}", PackName(folders[0]));
    return I18n::Tr(folders.size() == 2 ? "Download both" : "Download all");
}

std::string SizeText(uint32_t kb)
{
    return kb < 1024 ? I18n::Trf("{} KB", std::max<uint32_t>(1, kb)) : I18n::Trf("{:.1f} MB", kb / 1024.0);
}

// Starts downloads and shows their progress in Get shader packs
void DownloadPacks(const std::vector<std::string>& folders)
{
    Looks::Packs::Download(folders);
    g_scrollToPacks = true;
}

// ---------------------------------------------------------------------------------------------- import and folder
std::mutex g_pickLock;
std::optional<std::wstring> g_picked;
std::atomic<bool> g_pickBusy{ false };
std::string g_message;     // translated, under the Look row
bool g_messageError = false;

// The native file picker for the Import button, off the render thread (it pumps the game window's messages)
void PickPreset()
{
    if (g_pickBusy.exchange(true)) return;
    std::wstring label = ApexUtil::ToWide(I18n::Tr("ReShade presets"));
    if (!HookGuard::StartDetached("Looks: import a preset", [label = std::move(label)] {
        std::optional<std::wstring> picked;
        struct Finish
        {
            std::optional<std::wstring>& picked;
            ~Finish() { std::lock_guard<std::mutex> lock(g_pickLock); g_picked = std::move(picked); g_pickBusy = false; }
        } finish{ picked };
        const HRESULT com = CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED);
        if (FAILED(com)) return;
        IFileDialog* dialog = nullptr;
        if (SUCCEEDED(CoCreateInstance(CLSID_FileOpenDialog, nullptr, CLSCTX_INPROC_SERVER, IID_PPV_ARGS(&dialog))))
        {
            const COMDLG_FILTERSPEC types[] = { { label.c_str(), L"*.ini" } };
            dialog->SetFileTypes(1, types);
            DWORD options = 0;
            dialog->GetOptions(&options);
            dialog->SetOptions(options | FOS_FORCEFILESYSTEM | FOS_NOCHANGEDIR | FOS_FILEMUSTEXIST);
            if (SUCCEEDED(dialog->Show(nullptr)))
            {
                IShellItem* item = nullptr;
                if (SUCCEEDED(dialog->GetResult(&item)))
                {
                    PWSTR path = nullptr;
                    if (SUCCEEDED(item->GetDisplayName(SIGDN_FILESYSPATH, &path))) { picked = path; CoTaskMemFree(path); }
                    item->Release();
                }
            }
            dialog->Release();
        }
        CoUninitialize();
    })) g_pickBusy = false;
}

// Copies the picked .ini into Looks\ (a numbered name on a clash with another file; the same file is reused) and selects it
bool ImportPicked(const std::wstring& path)
{
    auto fail = [](const std::string& text) { g_message = text; g_messageError = true; return false; };
    std::string bytes;
    WIN32_FILE_ATTRIBUTE_DATA info{};
    if (!GetFileAttributesExW(path.c_str(), GetFileExInfoStandard, &info) || info.nFileSizeHigh || info.nFileSizeLow > Looks::kMaxPresetBytes ||
        !ApexUtil::ReadFileBytes(path, bytes) || bytes.size() > Looks::kMaxPresetBytes)
        return fail(I18n::Tr("This file can't be read as a preset"));
    Looks::Preset probe;
    Looks::ParsePreset(bytes, probe);
    const auto top = probe.sections.find("");
    if (top == probe.sections.end() || (!top->second.count("Techniques") && !top->second.count("TechniqueSorting")))
        return fail(I18n::Tr("This file is not a ReShade preset"));
    std::string name = ApexUtil::ToUtf8(path.substr(path.find_last_of(L"\\/") + 1));
    if (!Looks::ValidLookFileName(name)) name = "Imported look.ini";
    std::string stored, why;
    if (!Looks::StoreLook(name, bytes, stored, nullptr, &why))
    {
        LOG_ERROR("[Looks] import failed: " + why);
        return fail(I18n::Tr("The preset could not be copied to the Looks folder"));
    }
    LOG_INFO("[Looks] imported " + ApexUtil::ToUtf8(path) + " as Looks\\" + stored);
    SelectLook("looks:" + stored);
    g_message = I18n::Trf("Imported as {}", Looks::RefName("looks:" + stored));
    g_messageError = false;
    ImportOffer offer;
    offer.look = Looks::RefName("looks:" + stored);
    offer.packs = MissingPacks(&offer.shaders);
    if (!offer.packs.empty()) g_offer = std::move(offer); else g_offer.reset();
    return true;
}

